public class Solution {
  public static long solve(int[][] a) {
    if (a.length == 0) return 0;
    int[] prev = new int[a[0].length + 1];
    long total = 0;
    for (int[] row : a) {
      int[] next = new int[prev.length];
      for (int c = 1; c < next.length; c++)
        if (row[c - 1] == 1) {
          next[c] = 1 + Math.min(prev[c], Math.min(prev[c - 1], next[c - 1]));
          total += next[c];
        }
      prev = next;
    }
    return total;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 1}, {1, 1}}));
  }
}

Best time to buy and sell stock.source:
import java.util.*;

public class Solution {
  public static long profit(int[] prices, int k, int fee, boolean cooldown) {
    if (k < 0 || fee < 0) throw new IllegalArgumentException();
    for (int p : prices) if (p < 0) throw new IllegalArgumentException();
    k = Math.min(k, prices.length / 2);
    long[][] next = new long[2][k + 1], after = new long[2][k + 1];
    for (int i = prices.length - 1; i >= 0; i--) {
      long[][] cur = new long[2][k + 1];
      for (int t = 1; t <= k; t++) {
        cur[0][t] = Math.max(next[0][t], -((long) prices[i]) + next[1][t]);
        cur[1][t] =
            Math.max(
                next[1][t], prices[i] - (long) fee + (cooldown ? after[0][t - 1] : next[0][t - 1]));
      }
      after = next;
      next = cur;
    }
    return next[0][k];
  }

  public static void main(String[] args) {
    System.out.println(profit(new int[] {7, 1, 5, 3, 6, 4}, 1, 0, false));
  }
}

