    Map<String, Integer> best = new HashMap<>();
    int answer = 0;
    for (String s : a) {
      int length = 1;
      for (int i = 0; i < s.length(); i++) {
        String prev = s.substring(0, i) + s.substring(i + 1);
        length = Math.max(length, best.getOrDefault(prev, 0) + 1);
      }
      best.put(s, Math.max(length, best.getOrDefault(s, 0)));
