    int[][] d = table(a, b);
    int i = a.length(), j = b.length();
    StringBuilder out = new StringBuilder();
    while (i > 0 && j > 0) {
      if (a.charAt(i - 1) == b.charAt(j - 1)) {
        out.append(a.charAt(--i));
        j--;
      } else if (d[i - 1][j] >= d[i][j - 1]) out.append(a.charAt(--i));
      else out.append(b.charAt(--j));
    }
    while (i > 0) out.append(a.charAt(--i));
    while (j > 0) out.append(b.charAt(--j));
    return out.reverse().toString();
  }

