        if (r == 0 && c == 0) d[c] = a[r][c];
        else if (r == 0) d[c] = d[c - 1] + a[r][c];
        else if (c == 0) d[c] += a[r][c];
        else d[c] = Math.min(d[c], d[c - 1]) + a[r][c];
      }
    return d[d.length - 1];
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 3, 1}, {1, 5, 1}, {4, 2, 1}}));
  }
}

